        category="furniture",
        title="Desk",
        price=25.0,
        published_on="2026-08-01"
    );
    newer = Post(
        owner_root="kai",
        kind="offer",
        category="essentials",
        title="Lamp",
        price=5.0,
        published_on="2026-08-05"
    );
    gone = Post(
        owner_root="kai",
        kind="offer",
        category="furniture",
        title="Old desk",
        price=10.0,
        done=True
    );
    ranked = rank_feed([mine, newer, fits, gone], "me", "2026-08-06");
    assert [p.title for p in ranked] == ["Desk", "Lamp"];
}

