def timeAgo(iso: str) -> str {
    if not iso {
        return "";
    }
    then = new(Date, iso);
    now = new(Date);
    ms = now.getTime() - then.getTime();
    if ms < 0 {
        ms = 0;
    }
    mins = int(ms / 60000);
    if mins < 1 {
        return "just now";
    }
    if mins < 60 {
        return str(mins) + "m ago";
    }
    hours = int(mins / 60);
    if hours < 24 {
        return str(hours) + "h ago";
    }
    days = int(hours / 24);
    if days < 31 {
        return str(days) + "d ago";
    }
    return iso[:10];
}

