}

async def:pub acceptEmailToken(token: str) -> SessionView {
    if not token { raise Exception("Verification did not return a session."); }
    jacSetToken(token);
    return await current_session();
}

"""Store a new shift under its employer, linked from its holder."""
def add_shift(e: Employer, sh: Shift) -> Shift {
    sh.employer = jid(e);
    if not sh.created {
        sh.created = now_s();
    }
    put(e, sh);
    st = employee_of(sh.student);
    if st is not None {
        also(st, sh);
    }
    return sh;
}

"""Move a shift to a new holder (or to nobody), keeping the employee->shift links in step."""
def set_holder(sh: Shift, sid: str) {
    if sh.student == sid {
        return;
    }
    old = employee_of(sh.student);
    if old is not None {
        unlink(old, sh);
    }
    sh.student = sid;
    new = employee_of(sid);
    if new is not None {
        also(new, sh);
    }
}

