def:pub advance_phase(session_id: str) -> Session | None {
    for s in [root-->][?:Session] {
        if jid(s) == session_id {
            ev_cycles = 1;
            for e in [root-->][?:Event] {
                if jid(e) == s.event_id {
                    ev_cycles = e.cycles;
                    break;
                }
            }
            if s.phase == "work" {
                if s.cycle_ix < ev_cycles - 1 {
                    s.phase = "break";
                } else {
                    s.phase = "done";
                    s.running = False;
                }
            } elif s.phase == "break" {
                s.cycle_ix += 1;
                s.phase = "work";
            }
            s.phase_started_at = now_iso();
            s.phase_elapsed_before_pause = 0;
            return s;
        }
    }
    return None;
}


