    # TODO: implement
}", "newText": "def federal_annual(taxable: float) -> float {
    tax = 0.0;
    lower = 0.0;
    for (upper, rate) in BRACKETS_2026 {
        if taxable <= lower {
            break;
        }
        tax += (min(taxable, upper) - lower) * rate;
        lower = upper;
    }
    return tax;
}"}]}

