}

impl RolesSection.deleteRole(name: str) -> None {
    if saving {
        return;
    }
    saving = True;
    try {
        root spawn DeleteRole(name=name);
        confirmDelete = "";
        await load();
        if onChanged {
            onChanged();
        }
    } except Exception as e {
        toast("Could not delete that role");
    }
    saving = False;
}

