def _nearest_place(hub: Hub, lat: float, lng: float) -> Place | None {
    best: Place | None = None;
    best_d: float = 1.0e9;
    for p in [hub -->][?:Place] {
        dx: float = p.lat - lat;
        dy: float = p.lng - lng;
        if dx < 0.0 {
            dx = 0.0 - dx;
        }
        if dy < 0.0 {
            dy = 0.0 - dy;
        }
        d: float = dx + dy;
        if d < best_d {
            best_d = d;
            best = p;
        }
    }
    return best;
