def _part_of_day(h24: int) -> str {
    if h24 < 12 {
        return "morning";
    }
    if h24 < 17 {
        return "afternoon";
    }
    if h24 < 21 {
        return "evening";
    }
    return "night";
}

def _clock(h24: int, minute: int) -> str {
    if h24 == 12 and minute == 0 {
        return "noon";
    }
    words = HOUR_WORDS[h24 % 12];
    if minute == 0 {
        return words;
    }
    return words + " " + MINUTE_WORDS.get(minute, f"{minute:02d}");
}

