def dict_str(data: dict, key: str) -> str {
    if key in data {
        return str(data[key]);
    }
    return "";
}

def dict_int(data: dict, key: str) -> int {
    if key in data {
        try {
            return int(data[key]);
        } except Exception as e {
            return 0;
        }
    }
    return 0;
}

