}", "newText": "def rate_check(keys: list[str], limit: int, window: float, now: float = -1.0) -> float {
    t = now if now >= 0.0 else time.time();
    with _lock {
        retry = 0.0;
        for k in keys {
            recent = [h for h in _hits.get(k, []) if t - h < window];
            _hits[k] = recent;
            if len(recent) >= limit {
                retry = max(retry, recent[0] + window - t);
            }
        }
        if retry > 0.0 {
            return round(retry, 1);
        }
        for k in keys {
            _hits[k].append(t);
        }
        return 0.0;
    }
}"}]}

